public class BankAccount {
    private String accountNumber;      // Encapsulated state
    private double balance;

    public BankAccount(String accNo, double initialBalance) {
        this.accountNumber = accNo;
        this.balance = Math.max(0, initialBalance);
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
        } else {
            throw new IllegalArgumentException("Invalid or insufficient funds");
        }
    }
    public double getBalance() { return balance; }
}

class Car {
    String model;         // Instance variable (heap)
    int speed;
    static int carCount;  // Static class variable (shared)

    Car(String model) {
        this.model = model;
        this.speed = 0;
        carCount++;       // Increments shared count
    }
    void accelerate(int delta) { this.speed += delta; }
}
