abstract class PaymentGateway {
    String merchantId;

    PaymentGateway(String id) { this.merchantId = id; } // Constructor allowed!

    // Concrete method shared by all gateways
    void logTransaction(double amount) {
        System.out.println("Logging payment: " + amount);
    }

    // Abstract method: must be implemented by subclasses
    abstract boolean processPayment(double amount);
}

class CreditCardPayment extends PaymentGateway {
    CreditCardPayment(String id) { super(id); }
    @Override
    boolean processPayment(double amount) {
        // Specific credit card validation logic
        return true;
    }
}

